import { renderHook } from '@testing-library/react-hooks';

import { RESPONSE_CODE } from '@proton/shared/lib/drive/constants';

import useLink from './useLink';

const mockRequest = jest.fn();
const mockSetLinks = jest.fn();
const mockGetLink = jest.fn();
const mockLinkMetaToEncryptedLink = jest.fn();

jest.mock('../_api', () => ({
    useDebouncedRequest: () => mockRequest,
    linkMetaToEncryptedLink: (...args: unknown[]) => mockLinkMetaToEncryptedLink(...args),
}));
jest.mock('../_crypto', () => ({ useDriveCrypto: () => ({ getVerificationKey: jest.fn() }) }));
jest.mock('../_shares', () => ({ useShare: () => ({ getSharePrivateKey: jest.fn() }) }));
jest.mock('../_utils', () => ({ useDebouncedFunction: () => (callback: (signal: AbortSignal) => unknown) => callback() }));
jest.mock('./useLinksKeys', () => () => ({}));
jest.mock('./useLinksState', () => () => ({ getLink: mockGetLink, setLinks: mockSetLinks }));

describe('useLink failed fetch backoff', () => {
    const signal = new AbortController().signal;

    beforeEach(() => {
        jest.useFakeTimers();
        jest.clearAllMocks();
        mockGetLink.mockReturnValue(undefined);
    });

    afterEach(() => {
        jest.runOnlyPendingTimers();
        jest.useRealTimers();
    });

    it.each([RESPONSE_CODE.NOT_FOUND, RESPONSE_CODE.NOT_ALLOWED, RESPONSE_CODE.INVALID_ID])(
        'reuses error code %s for the same link, then retries after backoff',
        async (code) => {
            const error = { data: { Code: code } };
            mockRequest.mockRejectedValue(error);
            const { result } = renderHook(() => useLink());

            await expect(result.current.getLink(signal, 'share', `missing-${code}`)).rejects.toBe(error);
            await expect(result.current.getLink(signal, 'share', `missing-${code}`)).rejects.toBe(error);
            expect(mockRequest).toHaveBeenCalledTimes(1);

            jest.advanceTimersByTime(30_000);
            await expect(result.current.getLink(signal, 'share', `missing-${code}`)).rejects.toBe(error);
            expect(mockRequest).toHaveBeenCalledTimes(2);
        }
    );

    it('does not block another link or share and processes a successful fetch', async () => {
        const error = { data: { Code: RESPONSE_CODE.NOT_FOUND } };
        const encrypted = { linkId: 'valid', name: 'encrypted' };
        mockRequest.mockRejectedValueOnce(error).mockResolvedValue({ Link: { LinkID: 'valid' } });
        mockLinkMetaToEncryptedLink.mockReturnValue(encrypted);
        const { result } = renderHook(() => useLink());

        await expect(result.current.setSignatureIssues(signal, 'share', 'missing', {})).rejects.toBe(error);
        await expect(result.current.setSignatureIssues(signal, 'share', 'valid', {})).resolves.toBeUndefined();
        expect(mockRequest).toHaveBeenCalledTimes(2);
        expect(mockLinkMetaToEncryptedLink).toHaveBeenCalledWith({ LinkID: 'valid' }, 'share');
        expect(mockSetLinks).toHaveBeenCalledWith('share', [{ encrypted: { ...encrypted, signatureIssues: {} } }]);
    });

    it('does not cache other failures', async () => {
        const error = { data: { Code: 5000 } };
        mockRequest.mockRejectedValue(error);
        const { result } = renderHook(() => useLink());

        await expect(result.current.getLink(signal, 'share', 'other-failure')).rejects.toBe(error);
        await expect(result.current.getLink(signal, 'share', 'other-failure')).rejects.toBe(error);
        expect(mockRequest).toHaveBeenCalledTimes(2);
    });
});

